	"golive__tip_broadcaster_1": "<b>DICA:</b> obrigado por entrar ao vivo! Dê boas-vindas às pessoas dizendo “olá” quando elas ingressarem no seu vídeo.",
	"golive__tip_broadcaster_10": "<b>DICA:</b> Obrigado por entrar ao vivo no X! ≺3",
	"golive__tip_broadcaster_2": "<b>DICA:</b> tente chamar as pessoas pelo nome quando elas ingressarem no seu vídeo ao vivo. Elas vão adorar!",
	"golive__tip_broadcaster_3": "<b>DICA:</b> entre ao vivo por pelo menos alguns minutos para que as pessoas encontrem você com mais facilidade.",
	"golive__tip_broadcaster_4": "<b>DICA:</b> pergunte aos espectadores de onde eles são. É uma ótima maneira de quebrar o gelo.",
	"golive__tip_broadcaster_5": "<b>DICA:</b> agradeça às pessoas por sintonizar e responda aos comentários enviados para que elas continuem assistindo.",
	"golive__tip_broadcaster_6": "<b>DICA:</b> se você perder a conexão ao entrar ao vivo, vá para algum lugar que tenha um sinal melhor.",
	"golive__tip_broadcaster_7": "<b>DICA:</b> peça às pessoas que sigam você para receber uma notificação na próxima vez que você entrar ao vivo.",
