	"identity_education_conditions": "Eu dou consentimento para o X e a Au10tix usar as imagens do meu documento e minha selfie, incluindo dados biométricos extraídos, para confirmar minha identidade e para fins de segurança relacionados do X, inclusive prevenção contra falsa identidade. A Au10tix pode armazenar esses dados por até 30 dias. {{}}Saiba mais{{}}",
