	"profile_smart_blocked_autoblocked_by_twitter_description": "\"Você sofreu um bloqueio automático temporário quanto à visualização e à interação com os posts de @%1$s. Isso aconteceu quando a pessoa estava no Modo de Segurança e detectamos suas interações como potencialmente nocivas ou repetitivas.\n\nSabemos que nem sempre acertamos a mão nos bloqueios automáticos, por isso estamos trabalhando para melhorar a detecção.\n\n{{}}O que%2$sé%2$so Modo de{{}}Segurança?\n\nVeja algumas maneiras de manter conversas saudáveis – e evitar um bloqueio automático.\"",
