	"ps__tip_broadcaster_1": "<b>DICA:</b> obrigado por transmitir! Diga \\\"olá\\\" às pessoas quando elas ingressarem.",
	"ps__tip_broadcaster_11": "<b>DICA:</b> obrigado por transmitir no Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>DICA:</b> chame os espectadores participantes pelo nome; eles ficarão felizes!",
	"ps__tip_broadcaster_3": "<b>DICA:</b> transmita por pelo menos alguns minutos para que as pessoas possam encontrar você com mais facilidade.",
	"ps__tip_broadcaster_4": "<b>DICA:</b> perguntar aos espectadores de onde eles são é uma ótima maneira de quebrar o gelo.",
	"ps__tip_broadcaster_5": "<b>DICA:</b> agradeça aos espectadores por sintonizar e responda aos comentários deles para mantê-los interessados.",
	"ps__tip_broadcaster_6": "<b>DICA:</b> se você perder a conexão durante a transmissão, vá para um lugar que tenha um sinal melhor.",
	"ps__tip_broadcaster_7": "<b>DICA:</b> peça aos espectadores que sigam você. Assim, eles poderão ser notificados quando você entrar ao vivo.",
	"ps__tip_broadcaster_8": "<b>DICA:</b> comece a transmissão dizendo \\\"olá\\\". Os espectadores que assistirem à reprise adorarão.",
	"ps__tip_broadcaster_9": "<b>DICA:</b> agradeça aos espectadores por assistir à transmissão antes de encerrá-la.",
	"ps__tip_pre_broadcast_1": "<b>DICA:</b> crie um título antes de iniciar a transmissão e conheça pessoas com interesses semelhantes!",
	"ps__tip_pre_broadcast_2": "<b>DICA:</b> um título descritivo ajuda as pessoas a entender o assunto da sua transmissão.",
	"ps__tip_pre_broadcast_3": "<b>DICA:</b> precisa de ideias? faça um tour, compartilhe um talento ou fale sobre um tópico de seu interesse.",
	"ps__tip_pre_broadcast_4": "<b>DICA:</b> verifique se você tem um sinal de celular forte antes de iniciar a transmissão.",
	"ps__tip_pre_broadcast_5": "<b>DICA:</b> compartilhe suas transmissões no X para alcançar mais espectadores.",
	"ps__tip_pre_broadcast_6": "<b>DICA:</b> se você segue pessoas que também seguem você, faça transmissões para elas de modo privado.",
	"ps__tip_pre_broadcast_8": "<b>DICA:</b> adicione uma hashtag relevante ao título para ajudar as pessoas a descobrir sua transmissão.",
	"ps__tip_pre_broadcast_9": "<b>DICA:</b> essas são as dicas que temos no momento. Obrigado por usar o Periscope!",
